import {csvInLanguage,getLanguage} from './i18n.js?v=0.2.2-cm20261103-r2';
import {countedOptions,normalizeFavorites} from './actuator-analysis.js?v=0.2.2-cm20261103-r2';
import {createActuatorPlot} from './actuator-plot.js?v=0.2.2-cm20261103-r2';
import './site-shell.js?v=0.2.2-cm20261103-r2';
import {metricDefinitions as defs,metricValue,formatMetric,filterActuators,sortActuators,csvForActuators,integrationLabel,driverLabel,parameterSide} from './actuator-logic.js?v=0.2.2-cm20261103-r2';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(p,key)=>formatMetric(p.metrics?.[key]);
function url(raw,page){try{const u=new URL(raw,location.href);if(!['http:','https:'].includes(u.protocol))return '#';if(page&&/\.pdf$/i.test(u.pathname))u.hash='page='+page;return u.href;}catch{return '#';}}
const state={family:'all',driver:'all',powerMin:null,powerMax:null,rpmMin:null,rpmMax:null,integration:'all',europeOnly:false,brands:new Set(),categories:new Set(),query:'',encoder:'all',torqueKind:'ratedTorque',torqueMin:null,torqueMax:null,ratioMin:null,ratioMax:null,massMax:null,sort:'featured',view:'cards',collection:'all'};
try{const view=localStorage.getItem('actuator-view');if(['cards','list','plot'].includes(view))state.view=view;state.collection=localStorage.getItem('actuator-collection')==='favorites'?'favorites':'all';}catch{}
let data,products=[],byId=new Map(),results=[],compareIds=[],detailId=null,detailTab='spec',toastTimer,favoriteIds=new Set(),plotter;
const keys=['torqueMin','torqueMax','ratioMin','ratioMax','massMax','powerMin','powerMax','rpmMin','rpmMax'];
const cylinder='<svg viewBox="0 0 80 80" aria-hidden="true"><ellipse cx="40" cy="25" rx="23" ry="13"/><path d="M17 25v27c0 8 10 14 23 14s23-6 23-14V25M23 39v10m34-10v10"/><ellipse cx="40" cy="24" rx="9" ry="5"/><path d="M40 19V9m-6 0h12"/></svg>';
function picture(p,extra=''){return p.image?.path?`<img src="${esc(p.image.path)}" alt="${esc(p.brand+' '+p.model)}产品图" loading="lazy" decoding="async" ${extra}>`:`<div class="actuator-image-pending">${cylinder}<span>产品图待补</span></div>`;}
const layer=p=>integrationLabel(p);
function metric(p,key,label){return `<div><span class="metric-label">${esc(label||defs[key]?.[0]||key)}</span><span class="metric-value ${metricValue(p,key)===null?'missing':''}">${esc(fmt(p,key))}${metricValue(p,key)!==null?'<small>'+esc(defs[key]?.[1]??'')+'</small>':''}</span></div>`;}
function addButton(p,table=false){const on=compareIds.includes(p.id);return `<button type="button" class="compare-add ${table?'table-compare':''} ${on?'selected':''}" data-compare="${esc(p.id)}" aria-label="${on?'移除':'加入'}${esc(p.model)}参数对比" aria-pressed="${on}">${on?'✓':'+'}</button>`;}

function favoriteButton(p,table=false){const on=favoriteIds.has(p.id);return `<button type="button" class="favorite-toggle ${table?'table-favorite':''} ${on?'saved':''}" data-favorite="${esc(p.id)}" aria-label="${on?'取消收藏':'收藏'} ${esc(p.model)}" title="${on?'取消收藏':'收藏'} ${esc(p.model)}" aria-pressed="${on}">${on?'★':'☆'}</button>`;}
function saveFavorites(){try{localStorage.setItem('atlas-actuator-favorites',JSON.stringify([...favoriteIds]));}catch{toast('当前浏览器未允许保存收藏，本次仍可使用。');}}
function toggleFavorite(id){if(!byId.has(id))return;favoriteIds.has(id)?favoriteIds.delete(id):favoriteIds.add(id);saveFavorites();render();if(detailId){const top=$('#detailDialog').scrollTop;renderDetail();$('#detailDialog').scrollTop=top;}}
function renderCollection(){const all=$('#collectionAll'),favorites=$('#collectionFavorites');all.classList.toggle('active',state.collection==='all');favorites.classList.toggle('active',state.collection==='favorites');all.setAttribute('aria-pressed',state.collection==='all');favorites.setAttribute('aria-pressed',state.collection==='favorites');$('#favoriteCount').textContent=favoriteIds.size;$('#saveResults').disabled=!results.length||results.every(p=>favoriteIds.has(p.id));$('#clearFavorites').disabled=!favoriteIds.size;$('#sortSelect').disabled=state.view==='plot';}
function encoderBadge(p){return `<span class="encoder-tag ${p.encoder==='未披露'?'unknown':''}">${esc(p.encoder==='未披露'?'编码器待核':p.encoder)}</span>`;}
function card(p){const limitKey=metricValue(p,'peakTorque')!==null?'peakTorque':'stallTorque';return `<article class="robot-card actuator-card">${favoriteButton(p)}${addButton(p)}<button type="button" class="card-open" data-open="${esc(p.id)}" aria-label="查看 ${esc(p.model)} 详情"><div class="card-media"><span class="type-tag">${esc(p.category)}</span>${picture(p)}</div><div class="card-content"><p class="card-brand">${esc(p.brand)}</p><div class="card-title-line"><h3>${esc(p.model)}</h3></div><p class="card-subtitle">${esc(p.position||p.series||p.transmission)}</p><p class="scope-tag">${esc(layer(p))}</p><div class="card-metrics">${metric(p,'ratedTorque','额定 / 连续扭矩')}${metric(p,limitKey,limitKey==='peakTorque'?'峰值扭矩':'堵转扭矩')}${metric(p,'ratio','减速比')}${metric(p,'massKg','记录对象质量')}</div><p class="actuator-secondary">${p.metrics.ratedPower?esc(fmt(p,'ratedPower'))+' W · ':''}${p.metrics.ratedRpm?esc(fmt(p,'ratedRpm'))+' rpm · ':''}${p.driverIncluded?esc(driverLabel(p)):''}</p><div class="card-bottom">${encoderBadge(p)}<span class="card-source">${p.page?'PDF P.'+p.page:'官方资料'}</span><span class="card-detail-link">详情 →</span></div></div></button></article>`;}
function table(records){return `<div class="robot-list-wrap"><table class="robot-table actuator-table"><thead><tr><th>品牌 / 型号</th><th>门类</th><th class="num">额定 N·m</th><th class="num">峰值 N·m</th><th class="num">堵转 N·m</th><th class="num">减速比</th><th class="num">额定 W</th><th class="num">额定 rpm</th><th>驱动器配置</th><th>编码器</th><th class="num">质量 kg</th><th>收藏</th><th>对比</th></tr></thead><tbody>${records.map(p=>`<tr><td><button type="button" class="table-robot" data-open="${esc(p.id)}">${p.image?picture(p):'<span class="table-placeholder"></span>'}<span><strong>${esc(p.model)}</strong><small>${esc(p.brand)}</small></span></button></td><td>${esc(p.category)}<small class="layer-small">${esc(layer(p))}</small></td>${['ratedTorque','peakTorque','stallTorque','ratio'].map(k=>`<td class="num">${esc(fmt(p,k))}</td>`).join('')}<td class="num">${esc(fmt(p,'ratedPower'))}</td><td class="num">${esc(fmt(p,'ratedRpm'))}</td><td>${esc(driverLabel(p))}</td><td>${encoderBadge(p)}</td><td class="num">${esc(fmt(p,'massKg'))}</td><td>${favoriteButton(p,true)}</td><td>${addButton(p,true)}</td></tr>`).join('')}</tbody></table></div>`;}
function renderFilterLists(){$('#seriesFilter').innerHTML='<option value="all">全部产品系列</option>'+[...new Set(products.map(p=>p.productFamily).filter(Boolean))].sort().map(name=>'<option value="'+esc(name)+'">CubeMars '+esc(name)+'</option>').join('');for(const [field,target]of [['brand','brandFilters'],['category','categoryFilters']]){const names=countedOptions(products,field);$('#'+target).innerHTML=names.map(({value:name,count})=>`<label class="check-row"><input type="checkbox" name="${field}" value="${esc(name)}"><span>${esc(name)}</span><span class="brand-count">${count}</span></label>`).join('');}}

function chips(){$('.category-disclosure summary span').textContent=state.categories.size?state.categories.size+' 项已选':'全部 / 展开';const items=[];if(state.europeOnly)items.push(['europeOnly','欧洲科研补充']);if(state.integration!=='all')items.push(['integration',integrationLabel({integration:state.integration})]);if(state.family!=='all')items.push(['family','CubeMars '+state.family]);if(state.driver!=='all')items.push(['driver',driverLabel({driverIncluded:state.driver})]);for(const b of state.brands)items.push(['brand:'+b,b]);for(const c of state.categories)items.push(['category:'+c,c]);if(state.encoder!=='all')items.push(['encoder',state.encoder]);if(state.query)items.push(['query','搜索：'+state.query]);for(const k of keys)if(state[k]!==null)items.push([k,({torqueMin:defs[state.torqueKind][0]+' ≥ ',torqueMax:defs[state.torqueKind][0]+' ≤ ',ratioMin:'减速比 ≥ ',ratioMax:'减速比 ≤ ',massMax:'质量 ≤ ',powerMin:'额定功率 ≥ ',powerMax:'额定功率 ≤ ',rpmMin:'额定转速 ≥ ',rpmMax:'额定转速 ≤ '})[k]+state[k]+(k.startsWith('torque')?' N·m':k==='massMax'?' kg':k.startsWith('power')?' W':k.startsWith('rpm')?' rpm':':1')]);$('#activeFilters').hidden=!items.length;$('#activeFilters').innerHTML=items.map(([k,v])=>`<button type="button" class="filter-chip" data-clear="${esc(k)}" aria-label="移除筛选 ${esc(v)}">${esc(v)} ×</button>`).join('');}
function render(){if(!data)return;results=sortActuators(filterActuators(products,state),state.sort).filter(p=>state.collection!=='favorites'||favoriteIds.has(p.id));$('#resultCount').textContent=results.length;$('#resultsContent').className=state.view==='cards'?'robot-grid':state.view==='plot'?'actuator-workbench':'';if(state.view==='plot')plotter.render($('#resultsContent'),results);else $('#resultsContent').innerHTML=results.length?(state.view==='cards'?results.map(card).join(''):table(results)):state.collection==='favorites'?'<div class="empty-state"><h3>收藏夹中暂无匹配的电机</h3><p>点击型号卡片上的星标加入收藏，或放宽当前筛选。</p><button type="button" class="button button-primary" data-collection="all">浏览全部电机</button></div>':'<div class="empty-state"><h3>没有符合条件的驱动器</h3><p>尝试调整扭矩口径或放宽范围。缺失的指标不会按 0 计算。</p><button type="button" class="button button-primary" data-reset>清除筛选</button></div>';$$('[data-view]').forEach(b=>{const on=b.dataset.view===state.view;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on)});renderCollection();chips();}

function reset(){keys.forEach(k=>state[k]=null);Object.assign(state,{family:'all',driver:'all',integration:'all',europeOnly:false,brands:new Set(),categories:new Set(),query:'',encoder:'all',torqueKind:'ratedTorque',torqueMin:null,torqueMax:null,ratioMin:null,ratioMax:null,massMax:null});$('#integrationFilter').value='all';$('#seriesFilter').value='all';$('#driverFilter').value='all';$('#europeOnly').checked=false;$('#searchInput').value='';$('#encoderFilter').value='all';$('#torqueKind').value='ratedTorque';keys.forEach(k=>$('#'+k).value='');$$('input[name=brand],input[name=category]').forEach(e=>e.checked=false);render();}
function removeChip(key){if(key==='family'||key==='driver'){state[key]='all';$('#'+(key==='family'?'seriesFilter':'driverFilter')).value='all';render();return;}if(key==='europeOnly'){state.europeOnly=false;$('#europeOnly').checked=false;render();return;}if(key==='integration'){state.integration='all';$('#integrationFilter').value='all';render();return;}if(key.startsWith('brand:')){const name=key.slice(6);state.brands.delete(name);$$('input[name=brand]').find(e=>e.value===name).checked=false;}else if(key.startsWith('category:')){const name=key.slice(9);state.categories.delete(name);$$('input[name=category]').find(e=>e.value===name).checked=false;}else if(key==='query'){state.query='';$('#searchInput').value='';}else if(key==='encoder'){state.encoder='all';$('#encoderFilter').value='all';}else{state[key]=null;$('#'+key).value='';}render();}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,2600);}
function showDialog(id){const d=$('#'+id);if(!d.open)d.showModal();document.body.classList.add('dialog-open');}
function closeDialog(id){$('#'+id).close();if(!$$('dialog').some(d=>d.open))document.body.classList.remove('dialog-open');if(id==='detailDialog'){detailId=null;history.replaceState(null,'',location.pathname+location.search);}}
function sourceLink(id,page,label){const s=data.sources[id];return s?`<a href="${esc(url(s.url,page))}" target="_blank" rel="noopener noreferrer">${esc(label||id+(page?' · PDF p.'+page:''))} ↗</a>`:'来源待核';}
function sourceIds(p){return [...new Set([...(p.sourceIds??[]),...Object.values(p.metrics??{}).map(m=>m.source)])].filter(id=>data.sources[id]);}
function specs(p){return `<div class="detail-note"><strong>${esc(layer(p))}</strong>${esc(p.integration==='geared'?'本条为电机与减速器机械单元，外配驱动器；扭矩与转速已是减速器输出端，勿再乘一次内置减速比。':parameterSide(p)==='motor'?'数值为电机轴端或定转子本体；驱动器配置单独列示，外部传动另计。':'扭矩为所列模组输出端口径，外部腿部传动比另行计算。')}${p.availability?'<br>供货：'+esc(p.availability):''}</div>${p.projectSelection?'<div class="actuator-project-note"><strong>本项目选型记录</strong><p>'+esc(p.projectSelection.note)+'</p></div>':''}<h3 class="detail-section-title">驱动与传动参数 <span>按原始资料保留口径</span></h3><div class="spec-grid actuator-specs">${Object.entries(defs).map(([k,[label,unit]])=>{const m=p.metrics[k];return `<div class="spec-row"><span>${esc(label)}</span><strong class="${m?'':'missing'}">${esc(fmt(p,k))}${m?' '+esc(unit):''}</strong><small>${esc(m?.condition||(!m?(k==='ratio'&&p.integration==='motor'?'不适用：本条不含减速器':'该版本未披露或待核实'):'原文未进一步披露测试条件'))}${m?' · '+sourceLink(m.source,m.page):''}</small></div>`;}).join('')}<div class="spec-row"><span>驱动器配置</span><strong>${esc(driverLabel(p))}</strong><small>${esc(p.driverNote||'供货配置与外部控制器需按具体版本核对')}</small></div><div class="spec-row"><span>编码器方案</span><strong>${esc(p.encoder)}</strong><small>${esc(p.encoderDetail)}</small></div><div class="spec-row"><span>通讯接口</span><strong>${esc((p.protocol??[]).join(' / ')||(p.driverIncluded==='no'||p.integration==='motor'?'不适用：外配驱动器':'未披露'))}</strong><small>接口、电气版本与控制模式以对应手册为准</small></div><div class="spec-row"><span>减速机构</span><strong style="font:12px var(--font);max-width:250px">${esc(p.transmission||'未披露')}</strong><small>${esc(p.series||'')}</small></div></div>${p.notes?`<div class="detail-note"><strong>这条记录的使用边界</strong>${esc(p.notes)}</div>`:''}`;}
function associations(p){const links=p.robotProducts??[];return `${p.adoption?`<h3 class="detail-section-title">科研采用证据 <span>${esc(p.origin||'')}</span></h3><p class="detail-position">${esc(p.adoption.summary)}</p>${(p.adoption.evidence||[]).map(e=>`<article class="source-card"><h4>${esc(e.title)}</h4><p>${esc(e.kind)} · ${esc(e.note)}</p><a href="${esc(url(e.url))}" target="_blank" rel="noopener noreferrer">查看采用证据 ↗</a></article>`).join('')}`:''}<h3 class="detail-section-title">机器人本体关联 <span>${links.length} 条记录</span></h3>${links.length?`<div class="linkage-list">${links.map(r=>{if(typeof r==='string')r={name:r,status:'关联证据待完善'};return `<div class="linkage-item"><strong>${esc(r.name)}</strong><small>${esc(r.status||'确认状态待核')}</small>${r.source?sourceLink(r.source,null,'关联证据'):''}${r.platformId?`<a href="quadrupeds.html#robot/${encodeURIComponent(r.platformId)}">查看整机记录 ↗</a>`:''}${r.note?`<p>${esc(r.note)}</p>`:''}</div>`;}).join('')}</div>`:'<div class="detail-empty">尚未收录这个型号的已验证整机搭载关系。可以先用于选型比较，后续补充关节轴位、实装版本与证据。</div>'}<div class="actuator-conditions">同系列电机与机器人产品的关联，不代表所有关节轴都使用同一型号，也不代表电机模组输出与膝关节末端扭矩相同。</div>`;}
function evidence(p){return `<h3 class="detail-section-title">原始资料 <span>核查于 ${esc(p.reviewedOn||data.asof)}</span></h3>${sourceIds(p).map(id=>{const s=data.sources[id];return `<article class="source-card"><h4><code>${esc(id)}</code>${esc(s.title)}</h4><p>${esc(s.kind)} · ${esc(s.version)}</p><p>${esc(s.locator||'')}${p.page?' · 型号所在 PDF p.'+p.page:''}</p>${sourceLink(id,p.page,'打开原始资料')}</article>`;}).join('')}<p class="actuator-conditions">每个数值的原文条件和页码可在「规格与传感」中逐项查看。页面中的 PDF 页码按文件物理页数从 1 计数。</p>${p.image?`<article class="source-card"><h4>产品图片</h4><p>${esc(p.image.caption||'产品参考图')}</p><a href="${esc(url(p.image.pageUrl))}" target="_blank" rel="noopener noreferrer">${esc(p.image.credit)} · 图片出处 ↗</a></article>`:''}`;}
function renderDetail(){const p=byId.get(detailId);if(!p)return;$('#detailContent').innerHTML=`<div class="dialog-top"><div><p class="eyebrow">${esc(p.brand)} / ACTUATOR PROFILE</p><h2>${esc(p.model)}</h2></div><button type="button" class="icon-button" data-close="detailDialog" aria-label="关闭驱动器详情">×</button></div><div class="detail-main"><div><div class="detail-hero-media">${picture(p,'fetchpriority="high"')}</div><p class="photo-caption">${esc(p.image?.caption||'该型号产品图片待补。')}${p.image?'<br>图片：'+esc(p.image.credit):''}</p><div class="detail-classifications"><span>${esc(p.category)}</span><span>${esc(p.encoder)}</span><span>${esc(layer(p))}</span><span>${Object.keys(p.metrics).length} 项数值</span></div></div><div><div class="detail-meta"><code>${esc(p.id)}</code><span>${esc(p.series||'')}</span></div><p class="detail-position">${esc(p.position||'关节驱动与机器人本体选型')}</p>${p.aliases?.length?'<p class="actuator-scope">手册并列编号：'+esc(p.aliases.join(' / '))+'</p>':''}<p class="actuator-scope">${esc(p.encoderDetail||'编码器结构待披露')}<br>${esc((p.protocol??[]).join(' / ')||(p.driverIncluded==='no'||p.integration==='motor'?'通讯接口取决于外配驱动器':'通讯接口待披露'))}</p><div class="detail-top-metrics">${metric(p,'ratedTorque','额定 / 连续')}${metric(p,'peakTorque','峰值')}${metric(p,'stallTorque','堵转')}</div><div class="detail-top-metrics">${metric(p,'ratio','减速比')}${metric(p,'massKg','记录对象质量')}${metric(p,'voltage','电压')}</div></div></div><div class="detail-tabs" role="tablist" aria-label="驱动器详情内容">${[['spec','规格与传感'],['robots','科研与整机关联'],['evidence','证据来源']].map(([k,label])=>`<button type="button" role="tab" id="tab-${k}" data-tab="${k}" aria-selected="${detailTab===k}" aria-controls="detailTabBody" class="${detailTab===k?'active':''}">${label}</button>`).join('')}</div><div id="detailTabBody" class="detail-body" role="tabpanel" aria-labelledby="tab-${detailTab}">${detailTab==='spec'?specs(p):detailTab==='robots'?associations(p):evidence(p)}</div><div class="detail-actions"><button type="button" class="button button-outline" data-favorite="${esc(p.id)}">${favoriteIds.has(p.id)?'★ 已收藏':'☆ 收藏型号'}</button><button type="button" class="button button-outline" id="copyLink">复制详情链接</button><button type="button" class="button button-primary" data-compare="${esc(p.id)}">${compareIds.includes(p.id)?'已加入对比 ✓':'加入参数对比 +'}</button></div>`;}
function openDetail(id){if(!byId.has(id))return;detailId=id;detailTab='spec';renderDetail();history.replaceState(null,'','#actuator/'+encodeURIComponent(id));showDialog('detailDialog');$('#detailDialog').scrollTop=0;}
function renderTray(){$('#compareTray').hidden=compareIds.length===0;$('#compareCount').textContent=compareIds.length+' 个待比较';$('#compareNames').textContent=compareIds.map(id=>byId.get(id).model).join(' / ');$('#compareButton').disabled=compareIds.length<2;}
function toggleCompare(id){if(compareIds.includes(id))compareIds=compareIds.filter(x=>x!==id);else{if(compareIds.length>=4){toast('一次最多对比 4 个型号');return;}compareIds.push(id);}render();renderTray();if(detailId){const top=$('#detailDialog').scrollTop;renderDetail();$('#detailDialog').scrollTop=top;}}
function compare(){if(compareIds.length<2)return;const ps=compareIds.map(id=>byId.get(id));const rows=[...Object.entries(defs).map(([k,[label,unit]])=>[label+' ('+unit+')',p=>fmt(p,k)]),['集成层级',p=>layer(p)],['驱动器配置',p=>driverLabel(p)],['供货状态',p=>p.availability],['编码器方案',p=>p.encoder],['编码器说明',p=>p.encoderDetail],['减速机构',p=>p.transmission],['通讯',p=>(p.protocol??[]).join(' / ')],['参数使用边界',p=>p.notes]];$('#compareContent').innerHTML=`<div class="comparison-note">额定、峰值和堵转分别列出。请先核对集成层级：电机轴端值不能直接当作减速后的关节输出；各项工作条件随数值保留。</div><div class="comparison-scroll"><table class="comparison-table"><thead><tr><th>参数 / 条件</th>${ps.map(p=>`<th>${picture(p)}<h3>${esc(p.model)}</h3><small>${esc(p.brand)}<br>${esc(p.category)}</small></th>`).join('')}</tr></thead><tbody>${rows.map(([name,fn],i)=>`<tr><td>${esc(name)}</td>${ps.map(p=>{const key=i<Object.keys(defs).length?Object.keys(defs)[i]:null;return `<td class="${!key?'text-compare':''}">${esc(fn(p)||'—')}${key&&p.metrics[key]?.condition?'<small>'+esc(p.metrics[key].condition)+'</small>':''}</td>`;}).join('')}</tr>`).join('')}<tr><td>原始资料</td>${ps.map(p=>`<td>${sourceIds(p).map(id=>sourceLink(id,p.page)).join('<br>')}</td>`).join('')}</tr></tbody></table></div>`;showDialog('compareDialog');}
function exportResults(){const blob=new Blob([csvInLanguage(csvForActuators(results))],{type:'text/csv;charset=utf-8'});const href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=getLanguage()==='en'?`RobotBodyAtlas_Actuators_${results.length}.csv`:`本体图鉴_驱动器_${results.length}条.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);toast('已导出 '+results.length+' 条型号，包含参数条件与出处');}
function filters(open){$('#filterPanel').classList.toggle('open',open);$('#filterShade').hidden=!open;$('#openFilters').setAttribute('aria-expanded',open);(open?$('#closeFilters'):$('#openFilters')).focus();}
document.addEventListener('click',async e=>{const favorite=e.target.closest('[data-favorite]');if(favorite)return toggleFavorite(favorite.dataset.favorite);const collection=e.target.closest('[data-collection]');if(collection){state.collection=collection.dataset.collection;try{localStorage.setItem('actuator-collection',state.collection);}catch{}const u=new URL(location.href);u.searchParams.set('collection',state.collection);history.replaceState(null,'',u.pathname+u.search+u.hash);render();return;}const a=e.target.closest('[data-open]');if(a)return openDetail(a.dataset.open);const c=e.target.closest('[data-compare]');if(c)return toggleCompare(c.dataset.compare);const close=e.target.closest('[data-close]');if(close)return closeDialog(close.dataset.close);const v=e.target.closest('[data-view]');if(v){state.view=v.dataset.view;try{localStorage.setItem('actuator-view',state.view)}catch{}const u=new URL(location.href);u.searchParams.set('view',state.view);history.replaceState(null,'',u.pathname+u.search+u.hash);return render();}const chip=e.target.closest('[data-clear]');if(chip)return removeChip(chip.dataset.clear);if(e.target.closest('[data-reset]'))return reset();const t=e.target.closest('[data-tab]');if(t){const top=$('#detailDialog').scrollTop;detailTab=t.dataset.tab;renderDetail();$('#detailDialog').scrollTop=top;$('#tab-'+detailTab).focus();return;}if(e.target.closest('#copyLink')){try{await navigator.clipboard.writeText(location.href);toast('已复制该型号的详情链接')}catch{toast('当前链接：'+location.href)}}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='seriesFilter'){state.family=t.value;render();}if(t.id==='driverFilter'){state.driver=t.value;render();}if(t.id==='integrationFilter'){state.integration=t.value;render();}if(t.id==='europeOnly'){state.europeOnly=t.checked;render();}if(t.name==='brand'){t.checked?state.brands.add(t.value):state.brands.delete(t.value);render();}if(t.name==='category'){t.checked?state.categories.add(t.value):state.categories.delete(t.value);render();}if(t.id==='encoderFilter'){state.encoder=t.value;render();}if(t.id==='torqueKind'){state.torqueKind=t.value;render();}if(t.id==='sortSelect'){state.sort=t.value;render();}});
$('#searchInput').addEventListener('input',e=>{state.query=e.target.value;render();});for(const key of keys)$('#'+key).addEventListener('input',e=>{state[key]=Number.isFinite(e.target.valueAsNumber)?e.target.valueAsNumber:null;render();});
$('#saveResults').onclick=()=>{results.forEach(p=>favoriteIds.add(p.id));saveFavorites();render();toast('已收藏当前筛选结果');};$('#clearFavorites').onclick=()=>{favoriteIds.clear();saveFavorites();render();toast('已清空收藏夹');};
$('#resetButton').onclick=reset;$('#exportButton').onclick=exportResults;$('#openFilters').onclick=()=>filters(true);$('#closeFilters').onclick=()=>filters(false);$('#filterShade').onclick=()=>filters(false);$('#compareButton').onclick=compare;$('#clearCompare').onclick=()=>{compareIds=[];render();renderTray();};for(const id of ['methodButton','dataButton'])$('#'+id).onclick=()=>showDialog('methodDialog');
$$('dialog').forEach(d=>{d.addEventListener('cancel',e=>{e.preventDefault();closeDialog(d.id);});d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d.id);});});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!$$('dialog').some(d=>d.open)){e.preventDefault();$('#searchInput').focus();}if(e.key==='Escape'&&$('#filterPanel').classList.contains('open'))filters(false);if(e.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const names=['spec','robots','evidence'];detailTab=names[(names.indexOf(detailTab)+(e.key==='ArrowRight'?1:2))%3];renderDetail();$('#tab-'+detailTab).focus();}});
function openHash(){const match=location.hash.match(/^#actuator\/(.+)$/);if(match){try{openDetail(decodeURIComponent(match[1]));}catch{}}else if($('#detailDialog').open)closeDialog('detailDialog');}
window.addEventListener('hashchange',openHash);
if(location.hash.startsWith('#robot/'))location.replace('quadrupeds.html'+location.hash);
try{const response=await fetch('data/actuators.json');if(!response.ok)throw Error('HTTP '+response.status);data=await response.json();products=data.products;byId=new Map(products.map(p=>[p.id,p]));try{favoriteIds=new Set(normalizeFavorites(JSON.parse(localStorage.getItem('atlas-actuator-favorites')||'[]'),byId.keys()));}catch{}plotter=createActuatorPlot({products,sources:data.sources,onFavorite:toggleFavorite,onOpen:openDetail,isFavorite:id=>favoriteIds.has(id),notify:toast});$('#productTotal').textContent=products.length;$('#brandTotal').textContent=new Set(products.map(p=>p.brand)).size;$('#metricTotal').textContent=products.reduce((n,p)=>n+Object.keys(p.metrics).length,0);$('#sourceDirectory').innerHTML=`<p>已收录 ${products.length} 条型号 / 电压配置，${Object.keys(data.sources).length} 份手册或官方页面。智身、达妙、高擎以用户提供手册为依据；其余以厂商手册、官网与科研论文为依据。欧洲采用证据见详情「科研与整机关联」与专题报告。</p>`;renderFilterLists();const params=new URLSearchParams(location.search);if(['cards','list','plot'].includes(params.get('view')))state.view=params.get('view');if(['all','favorites'].includes(params.get('collection')))state.collection=params.get('collection');if(params.get('scope')==='europe'){state.europeOnly=true;$('#europeOnly').checked=true;}const requestedBrand=params.get('brand'),matchedBrand=requestedBrand&&products.find(p=>p.brand===requestedBrand||(p.aliases||[]).includes(requestedBrand))?.brand;if(matchedBrand){state.brands.add(matchedBrand);$$('input[name=brand]').find(e=>e.value===matchedBrand).checked=true;}for(const [param,key,id]of [['family','family','seriesFilter'],['driver','driver','driverFilter'],['integration','integration','integrationFilter']]){const v=params.get(param);if(v&&[...$('#'+id).options].some(o=>o.value===v)){state[key]=v;$('#'+id).value=v;}}if(params.get('q')){state.query=params.get('q');$('#searchInput').value=state.query;}render();openHash();}catch(error){console.error(error);$('#resultsContent').innerHTML='<div class="empty-state"><h3>资料暂未载入</h3><p>请刷新页面重新载入。</p><a href="./" class="button button-outline">重新载入</a></div>';}

document.addEventListener('atlas:languagechange',()=>{if(state.view==='plot')plotter?.refreshLanguage();});
window.addEventListener('storage',e=>{if(e.key==='atlas-actuator-favorites'&&data){try{favoriteIds=new Set(normalizeFavorites(JSON.parse(e.newValue||'[]'),byId.keys()));render();}catch{}}});
